// Code generated by hertz generator.

package qrcode

import (
	"context"
	"fmt"
	"sync"

	"github.com/cloudwego/hertz/pkg/app"
	"github.com/cloudwego/hertz/pkg/protocol/consts"
	"github.com/pigeonbox/contracts/errcode"
	qrcode "github.com/pigeonbox/contracts/gen/qrcode"
	qrcodeservice "github.com/pigeonbox/core/app/qrcode"
)

// QRCodeStore 存储生成的二维码（内存存储）。
// 并发安全 + 容量上限：此前裸 map 无锁，两个并发 generate 即
// concurrent map writes fatal 整个进程（未认证可达 = 远程 DoS）。
var (
	qrcodeMu     sync.RWMutex
	QRCodeStore  = make(map[string]*StoredQRCode)
	qrcodeMaxCap = 10000
)

// qrcodePut 并发安全写入；超限时丢弃最早写入的条目（近似 LRU，防内存无界）
func qrcodePut(id string, qr *StoredQRCode) {
	qrcodeMu.Lock()
	defer qrcodeMu.Unlock()
	if len(QRCodeStore) >= qrcodeMaxCap {
		for k := range QRCodeStore {
			delete(QRCodeStore, k)
			break
		}
	}
	QRCodeStore[id] = qr
}

// qrcodeGet 并发安全读取
func qrcodeGet(id string) (*StoredQRCode, bool) {
	qrcodeMu.RLock()
	defer qrcodeMu.RUnlock()
	qr, ok := QRCodeStore[id]
	return qr, ok
}

// StoredQRCode 存储的二维码数据
type StoredQRCode struct {
	ID      string
	Data    []byte
	DataStr string
	Size    int
}

// GenerateQRCode .
// @router /qrcode/generate [POST]
func GenerateQRCode(ctx context.Context, c *app.RequestContext) {
	var err error
	var req qrcode.GenerateQRCodeReq
	err = c.BindAndValidate(&req)
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": err.Error(),
		})
		return
	}

	// 验证二维码数据
	if req.Data == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "二维码数据不能为空",
		})
		return
	}

	// 设置默认尺寸
	size := int(req.Size)
	if size <= 0 {
		size = 256
	}

	// 验证数据长度
	if len(req.Data) > 4296 {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeInvalidParam,
			"message": "二维码数据过长，最大支持4296个字符",
		})
		return
	}

	// 生成二维码
	pngData, err := qrcodeservice.GenerateQRCode(req.Data, size)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    errcode.CodeInternal,
			"message": "生成二维码失败: " + err.Error(),
		})
		return
	}

	// 生成唯一ID
	id := qrcodeservice.GenerateQRCodeID()

	// 存储二维码数据
	qrcodePut(id, &StoredQRCode{
		ID:      id,
		Data:    pngData,
		DataStr: req.Data,
		Size:    size,
	})

	// 构建响应
	resp := &qrcode.GenerateQRCodeResp{
		Code:    0,
		Message: "生成成功",
		Data: &qrcode.QRCodeData{
			ID:   id,
			Data: req.Data,
			Size: req.Size,
		},
	}

	// 如果需要返回base64数据
	if req.ReturnBase64 {
		base64Data, err := qrcodeservice.GenerateQRCodeBase64(req.Data, size)
		if err != nil {
			c.JSON(consts.StatusInternalServerError, map[string]interface{}{
				"code":    errcode.CodeInternal,
				"message": "生成base64数据失败: " + err.Error(),
			})
			return
		}
		resp.Data.Base64Data = base64Data
	} else {
		// 返回图片URL
		resp.Data.ImageURL = fmt.Sprintf("/qrcode/%s", id)
	}

	c.JSON(consts.StatusOK, resp)
}

// GetQRCode .
// @router /qrcode/:id [GET]
func GetQRCode(ctx context.Context, c *app.RequestContext) {
	var err error
	var req qrcode.GetQRCodeReq
	err = c.BindAndValidate(&req)
	if err != nil {
		c.String(consts.StatusBadRequest, err.Error())
		return
	}

	// 检查二维码是否存在
	storedQR, exists := qrcodeGet(req.ID)
	if !exists {
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    errcode.CodeNotFound,
			"message": "二维码不存在",
		})
		return
	}

	// 返回PNG图片
	c.SetContentType("image/png")
	_, _ = c.Write(storedQR.Data)
}
